def split(line):
    out, cur, quoted = [], '', False
    for ch in line:
        if ch == '"':
            quoted = not quoted
        elif ch.isspace() and not quoted:
            if cur:
                out.append(cur)
                cur = ''
        else:
            cur += ch
    if cur:
        out.append(cur)
    return out

import unittest
from mod import split
class T(unittest.TestCase):
    def test_plain(self):
        self.assertEqual(split('a  b'), ['a', 'b'])
        self.assertEqual(split('"a b" c'), ['a b', 'c'])

if __name__ == '__main__':
    unittest.main()

