def split(line):
    """Split a command line into a list of words.

    Whitespace outside quotes separates words. Inside single quotes every
    character is literal until the closing single quote. Inside double
    quotes a backslash followed by a double quote or another backslash
    yields that one character; any other backslash is kept as it is.
    Outside quotes a backslash makes the next character literal. Quotes do
    not create word boundaries. A quoted empty string is an empty word.
    A backslash at the very end of the line is kept as a character.
    An unterminated quote raises ValueError.
    """
    out = []
    cur = ''
    started = False  # current word has content or an opening quote
    state = 'normal'  # 'normal' | 'single' | 'double'
    i = 0
    n = len(line)
    while i < n:
        ch = line[i]
        if state == 'normal':
            if ch == "'":
                state = 'single'
                started = True
            elif ch == '"':
                state = 'double'
                started = True
            elif ch == '\\':
                if i + 1 < n:
                    cur += line[i + 1]  # next character is literal
                    i += 1
                else:
                    cur += '\\'  # backslash at end of line is kept
                started = True
            elif ch.isspace():
                if started:
                    out.append(cur)
                    cur = ''
                    started = False
            else:
                cur += ch
                started = True
        elif state == 'single':
            if ch == "'":
                state = 'normal'
            else:
                cur += ch  # every character is literal
        else:  # state == 'double'
            if ch == '"':
                state = 'normal'
            elif ch == '\\' and i + 1 < n and line[i + 1] in ('"', '\\'):
                cur += line[i + 1]  # escaped quote or backslash
                i += 1
            else:
                cur += ch  # any other backslash is kept as it is
        i += 1
    if state != 'normal':
        raise ValueError('unterminated quote')
    if started:
        out.append(cur)
    return out

